package com.prima.factory.scheduler; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import com.prima.factory.service.MonitoringService;
@Component public class RealtimePublisher { private final MonitoringService s;private final SimpMessagingTemplate ws;public RealtimePublisher(MonitoringService s,SimpMessagingTemplate ws){this.s=s;this.ws=ws;} @Scheduled(fixedDelay=1000) void publish(){var equipment=s.equipment();ws.convertAndSend("/topic/equipment-status",equipment);ws.convertAndSend("/topic/dashboard-kpi",s.dashboard());ws.convertAndSend("/topic/collection-health",s.collection());} }
